273	  /** Maps the engine-agnostic hooks onto the SDK's hook protocol. */
274	  private sdkHooks(hooks: SessionHooks): NonNullable<Options['hooks']> {
275	    const registered: NonNullable<Options['hooks']> = {}
276	    if (hooks.preToolUse) {
277	      const pre = hooks.preToolUse.bind(hooks)
278	      const callback: HookCallback = async (input): Promise<HookJSONOutput> => {
279	        if (input.hook_event_name !== 'PreToolUse') return {}
280	        const outcome = await pre({ toolName: bareToolName(input.tool_name), input: input.tool_input, toolUseId: input.tool_use_id })
281	        if (outcome && 'deny' in outcome) {
282	          return { hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: outcome.deny } }
283	        }
284	        if (!outcome?.allow && !outcome?.additionalContext) return {}
285	        return {
286	          hookSpecificOutput: {
287	            hookEventName: 'PreToolUse',
288	            ...(outcome.allow ? { permissionDecision: 'allow' } : {}),
289	            ...(outcome.additionalContext ? { additionalContext: outcome.additionalContext } : {}),
290	          },
291	        }
292	      }
293	      registered.PreToolUse = [{ hooks: [callback] }]
294	    }
295	    if (hooks.postToolUse) {
296	      const post = hooks.postToolUse.bind(hooks)
297	      const callback: HookCallback = async (input): Promise<HookJSONOutput> => {
298	        if (input.hook_event_name !== 'PostToolUse') return {}
299	        const output = typeof input.tool_response === 'string' ? input.tool_response : JSON.stringify(input.tool_response)
300	        const outcome = await post({
301	          toolName: bareToolName(input.tool_name),
302	          input: input.tool_input,
303	          toolUseId: input.tool_use_id,
304	          output,
305	          isError: false,
306	        })
307	        if (outcome?.additionalContext) {
308	          return { hookSpecificOutput: { hookEventName: 'PostToolUse', additionalContext: outcome.additionalContext } }
309	        }
310	        return {}
311	      }
312	      registered.PostToolUse = [{ hooks: [callback] }]
313	    }
314	    return registered
315	  }
