317	  private requestPermission(
318	    toolName: string,
319	    input: Record<string, unknown>,
320	    ctx: Parameters<NonNullable<Options['canUseTool']>>[2],
321	  ): Promise<PermissionResult> {
322	    return new Promise((resolve) => {
323	      const requestId = ctx.toolUseID
324	      this.pending.set(requestId, { resolve, input })
325	      ctx.signal.addEventListener('abort', () => {
326	        if (this.pending.delete(requestId)) resolve({ behavior: 'deny', message: 'Cancelled' })
327	      })
328	      this.output.push({
329	        type: 'permission_request',
330	        requestId,
331	        toolUseId: ctx.toolUseID,
332	        toolName: bareToolName(toolName),
333	        input,
334	        ...(ctx.title ? { title: ctx.title } : {}),
335	        ...(ctx.description ? { description: ctx.description } : {}),
336	      })
337	    })

1	/**
2	 * Engine-agnostic hook points. The Claude engine maps them onto the SDK's
3	 * PreToolUse / PostToolUse hooks, the own-loop engine calls them directly, so
4	 * a hook is written once.
5	 */
6	
7	export type ToolUse = { toolName: string; input: unknown; toolUseId: string }
8	
9	/** `allow` skips the permission prompt: the hook has ruled the call safe. */
10	export type PreToolUseOutcome =
11	  | { deny: string }
12	  | { allow?: true; additionalContext?: string }
13	  | undefined
14	
15	export type PostToolUseOutcome = { additionalContext?: string } | undefined
16	
17	export interface SessionHooks {
18	  preToolUse?(tool: ToolUse): Promise<PreToolUseOutcome>
19	  postToolUse?(tool: ToolUse & { output: string; isError: boolean }): Promise<PostToolUseOutcome>
20	}
21	
22	/** Runs several hooks in order: the first deny wins, any allow allows, contexts are joined. */
23	export function composeHooks(...hooks: SessionHooks[]): SessionHooks {
24	  return {
25	    async preToolUse(tool) {
26	      const contexts: string[] = []
27	      let allow = false
28	      for (const hook of hooks) {
29	        const outcome = await hook.preToolUse?.(tool)
30	        if (outcome && 'deny' in outcome) return outcome
31	        if (outcome?.allow) allow = true
32	        if (outcome?.additionalContext) contexts.push(outcome.additionalContext)
33	      }
34	      if (!allow && contexts.length === 0) return undefined
35	      return { ...(allow ? { allow: true as const } : {}), ...(contexts.length ? { additionalContext: contexts.join('\n\n') } : {}) }
36	    },
37	    async postToolUse(tool) {
38	      const contexts: string[] = []
39	      for (const hook of hooks) {
40	        const outcome = await hook.postToolUse?.(tool)
41	        if (outcome?.additionalContext) contexts.push(outcome.additionalContext)
42	      }
43	      return contexts.length ? { additionalContext: contexts.join('\n\n') } : undefined
44	    },
45	  }
46	}
